+const base = { actor: "drew", kind: "action-applied", ref: "gh:developing-today/code#1", summary: "did a thing" };
+const DAY_MS = 24 * 60 * 60 * 1000;
+const iso = (msAgo: number) => new Date(Date.now() - msAgo).toISOString();
